	// sees them. A trailing slash empties the final id of the device/session
	// routes and is rejected there for the same reason; the document routes
	// keep their pre-existing ServeMux behavior.
	return emptyIDGuard(mux)
}

// emptyIDGuard rejects requests carrying an empty path identifier with a 400
// JSON error instead of letting ServeMux emit its HTML redirect or a
// plain-text 404.
//
// The document family keeps its original rule (an empty documentID, i.e. the
// prefix /v1/documents//); other odd paths there retain their old response so
// the pre-existing surface is unchanged. The new device/session families are
// stricter: any doubled slash (an empty deviceId, sessionId or documentId
// segment) or a trailing slash (an empty final id) is a 400 JSON error.
func emptyIDGuard(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		p := r.URL.Path

		documentSegmentEmpty := strings.HasPrefix(p, "/v1/documents//")
		newFamilySegmentEmpty := false
		if strings.HasPrefix(p, "/v1/devices/") || strings.HasPrefix(p, "/v1/sessions/") {
			newFamilySegmentEmpty = strings.Contains(p, "//") || strings.HasSuffix(p, "/")
		}

		if documentSegmentEmpty || newFamilySegmentEmpty || malformedNewDocumentPath(p) || malformedSubscribePath(p) || malformedSessionCRDTPath(p) || malformedCRDTPath(p) || malformedSnapshotPath(p) {
			writeError(w, http.StatusBadRequest, "path identifiers must be non-empty strings")
			return
		}
		next.ServeHTTP(w, r)
	})
}

// malformedNewDocumentPath reports whether p targets one of the new
// long-poll/replay endpoints but is not that endpoint's exact location: a
// missing/empty segment, a trailing slash, extra segments, or a "poll"/"replay"
// segment in a position short of the registered shape. ServeMux would answer
// those with a 301 redirect or a plain-text 404/405; the new endpoints promise
// a JSON error and never a redirect, so every such path is a malformed 400.
//
// Keywords are matched only past the documentID position, so documents that
// happen to be named "poll" or "replay" keep their ordinary merge/snapshot/
// changes routes.
func malformedNewDocumentPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/documents/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")

	// Poll endpoint: "poll" must be exactly the third segment, after a
	// non-empty documentID and "changes".
	for i, seg := range segs {
		if seg == "poll" && i > 0 {
			return !(len(segs) == 3 && segs[0] != "" && segs[1] == "changes")
		}
	}
	// Replay endpoint: "replay" must be exactly the second segment, after a
	// non-empty documentID.
	for i, seg := range segs {
		if seg == "replay" && i > 0 {
			return !(len(segs) == 2 && segs[0] != "")
		}
	}
	return false
}

// malformedSubscribePath reports whether p targets the WebSocket subscription
// endpoint but is not at its exact location
// (/v1/sessions/{sessionId}/documents/{documentId}/changes/subscribe): a
// missing "documents"/"changes" segment, an extra segment, or a "subscribe"
// segment short of the registered shape. ServeMux would answer those with a
// plain-text 404/405; every failure of this endpoint must be a JSON 400
// instead. Empty segments are already rejected by the guard itself.
//
// "subscribe" is treated as the endpoint keyword only in the endpoint's
// terminal segment position (the fifth segment, index 4); a session or
// document identifier literally named "subscribe" occupies an identifier
// position (index 0 or 2) and is therefore left to the ordinary
// changes/subscribe routes like any other id.
func malformedSubscribePath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/sessions/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	// The CRDT namespace ("crdt" immediately past the document identifier)
	// has its own guard; "subscribe" there is not the changes-subscribe
	// keyword.
	if len(segs) >= 4 && segs[1] == "documents" && segs[3] == "crdt" {
		return false
	}
	for i, seg := range segs {
		if seg != "subscribe" {
			continue
		}
		// Identifier positions: sessionId (0) and documentId (2). A value of
		// "subscribe" there is an ordinary identifier, not the endpoint word.
		if i == 0 || i == 2 {
			continue
		}
		// Endpoint keyword position: the fifth segment must be exactly
		// "subscribe" with the documents/changes scaffolding around it, and no
		// segment may follow. Any other occurrence is a malformed path.
		if i == 4 && len(segs) == 5 &&
			segs[0] != "" &&
			segs[1] == "documents" &&
			segs[2] != "" &&
			segs[3] == "changes" {
			return false
		}
		return true
	}
	return false
}

// malformedSessionCRDTPath reports whether p targets the session-scoped CRDT
// namespace but is not at one of its two exact locations:
//
//	GET /v1/sessions/{sessionId}/documents/{documentId}/crdt/state
//	GET /v1/sessions/{sessionId}/documents/{documentId}/crdt/state/subscribe
//
// a missing "state"/"subscribe" segment, an extra segment, or a "crdt" segment
// in the keyword position (immediately past the document identifier) short of
// one of the registered shapes. ServeMux would answer those with a
// plain-text 404/405; every failure of these endpoints must be a JSON 400
// instead. Empty segments are already rejected by the guard itself.
//
// "crdt" is treated as the endpoint keyword only in the fourth segment (index
// 3, right after the document identifier); a session or document identifier
// literally named "crdt" occupies an identifier position (index 0 or 2) and
// keeps its ordinary routes.
func malformedSessionCRDTPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/sessions/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	if len(segs) < 4 || segs[1] != "documents" || segs[3] != "crdt" {
		return false
	}
	// Keyword position reached. The state read is exactly
	// {sessionId}/documents/{documentId}/crdt/state; the subscription adds
	// one trailing "subscribe" segment.
	validState := len(segs) == 5 &&
		segs[0] != "" &&
		segs[2] != "" &&
		segs[4] == "state"
	validSubscribe := len(segs) == 6 &&
		segs[0] != "" &&
		segs[2] != "" &&
		segs[4] == "state" &&
		segs[5] == "subscribe"
	return !(validState || validSubscribe)
}

// Handler exposes the HTTP surface over a private in-memory store. Use
// NewHandler with a durable store for real deployments.
func Handler() http.Handler {
	s, err := app.Open("")
	if err != nil {
		log.Fatalf("open in-memory app: %v", err)
	}
	return NewHandler(s)
}

// decodeJSONBody enforces the strict POST contract shared by every JSON
// endpoint: Content-Type must be application/json, the body is capped at
// maxBatchBytes, it must contain exactly one JSON value, and no trailing data
// may follow it. Any violation writes a 400 JSON error and returns false; the
// caller returns immediately, so no handler reaches the store with malformed
// input and rejected requests write nothing.
func decodeJSONBody(w http.ResponseWriter, r *http.Request, dst any) bool {
	mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil || mediaType != "application/json" {
		writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
		return false
	}

	r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
	dec := json.NewDecoder(r.Body)
	if err := dec.Decode(dst); err != nil {
		writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
		return false
	}
	// Reject trailing data after the JSON value.
	if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
		writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
		return false
	}
	return true
}

func handleRegisterDevice(s *app.App, w http.ResponseWriter, r *http.Request) {
	var req deviceRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}

	created, err := s.RegisterDevice(req.DeviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to register device")
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{"deviceId": req.DeviceID, "created": created})
}

func handleCreateSession(s *app.App, w http.ResponseWriter, r *http.Request) {
	deviceID := r.PathValue("deviceId") // route pattern + guard guarantee non-empty

	var req sessionRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.SessionID == "" {
		writeError(w, http.StatusBadRequest, "sessionId must be a non-empty string")
		return
	}

	created, err := s.CreateSession(deviceID, req.SessionID)
	if err != nil {
		var conflict *store.ErrSessionConflict
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			writeError(w, http.StatusNotFound, "device not found")
		case errors.As(err, &conflict):
			writeError(w, http.StatusConflict, "sessionId already belongs to another device: "+conflict.ID)
		default:
			writeError(w, http.StatusInternalServerError, "failed to create session")
		}
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{"sessionId": req.SessionID, "created": created})
}

func handleDeleteSession(s *app.App, w http.ResponseWriter, r *http.Request) {
	deviceID := r.PathValue("deviceId")   // route pattern + guard guarantee non-empty
	sessionID := r.PathValue("sessionId") // route pattern + guard guarantee non-empty

	if err := s.DeleteSession(deviceID, sessionID); err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to delete session")
		return
	}

	writeJSON(w, http.StatusOK, map[string]bool{"deleted": true})
}

func handlePostChanges(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern guarantees non-empty

	mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil || mediaType != "application/json" {
		writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
		return
	}

	r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
	var req postRequest
	dec := json.NewDecoder(r.Body)
	if err := dec.Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
		return
	}
	// Reject trailing data after the JSON object.
	if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
		writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
		return
	}

	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}
	if len(req.Changes) == 0 {
		writeError(w, http.StatusBadRequest, "changes must be a non-empty array")
		return
	}

	changes := make([]events.Change, len(req.Changes))
	seen := make(map[string]struct{}, len(req.Changes))
	for i, c := range req.Changes {
		if c.ID == "" {
			writeError(w, http.StatusBadRequest, "each change must have a non-empty string id")
			return
		}
		if len(c.Payload) == 0 {
			writeError(w, http.StatusBadRequest, "each change must carry a JSON payload")
			return
		}
		if _, dup := seen[c.ID]; dup {
			writeError(w, http.StatusBadRequest, "duplicate change id within batch: "+c.ID)
			return
		}
		seen[c.ID] = struct{}{}
		changes[i] = events.Change{ID: c.ID, DeviceID: req.DeviceID, Payload: c.Payload}
	}

	results, err := s.PostChanges(documentID, changes)
	if err != nil {
		var conflict *events.ErrConflict
		if errors.As(err, &conflict) {
			writeError(w, http.StatusConflict, "change id already exists with different deviceId or payload: "+conflict.ID)
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to commit changes")
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{"results": results})
}

func handleMergeChange(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern guarantees non-empty

	mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil || mediaType != "application/json" {
		writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
		return
	}

	r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
	var req mergeRequest
	dec := json.NewDecoder(r.Body)
	if err := dec.Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
		return
	}
	if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
		writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
		return
	}

	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}
	// baseCursor must be present and a non-negative integer (no fractions,
	// strings, booleans or null).
	if len(req.BaseCursor) == 0 {
		writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
		return
	}
	baseCursor, ok := parseNonNegativeInt(req.BaseCursor)
	if !ok {
		writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
		return
	}
	if req.Change == nil {
		writeError(w, http.StatusBadRequest, "change must be an object")
		return
	}
	if req.Change.ID == "" {
		writeError(w, http.StatusBadRequest, "change.id must be a non-empty string")
		return
	}
	if len(req.Change.Payload) == 0 || !isJSONObject(req.Change.Payload) {
		writeError(w, http.StatusBadRequest, "change.payload must be a JSON object")
		return
	}

	result, err := s.MergeChange(documentID, baseCursor, events.Change{
		ID:       req.Change.ID,
		DeviceID: req.DeviceID,
		Payload:  req.Change.Payload,
	})
	if err != nil {
		var conflict *events.ErrConflict
		switch {
		case errors.Is(err, events.ErrStaleCursor):
			writeError(w, http.StatusBadRequest, "baseCursor is unknown or greater than the current cursor")
			return
		case errors.As(err, &conflict):
			writeError(w, http.StatusConflict, "merge conflicts with existing changes: "+conflict.ID)
			return
		default:
			writeError(w, http.StatusInternalServerError, "failed to merge change")
			return
		}
	}

	writeJSON(w, http.StatusOK, result)
}

func handlePostSnapshot(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern guarantees non-empty

	mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil || mediaType != "application/json" {
		writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
		return
	}

	r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
	var req snapshotPostRequest
	dec := json.NewDecoder(r.Body)
	if err := dec.Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
		return
	}
	if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
		writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
		return
	}

	cursor, ok := parseNonNegativeInt(req.Cursor)
	if !ok {
		writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
		return
	}
	if len(req.State) == 0 {
		writeError(w, http.StatusBadRequest, "state is required")
		return
	}

	created, err := s.PutSnapshot(documentID, cursor, req.State)
	if err != nil {
		var conflict *events.ErrSnapshotConflict
		switch {
		case errors.Is(err, events.ErrSnapshotBase):
			writeError(w, http.StatusBadRequest, "document is unknown or cursor is not an existing cursor")
			return
		case errors.As(err, &conflict):
			writeError(w, http.StatusConflict, "snapshot already exists with a different state")
			return
		default:
			writeError(w, http.StatusInternalServerError, "failed to store snapshot")
			return
		}
	}

	writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "created": created})
}

func handleGetSnapshot(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern guarantees non-empty

	cursor, ok := parseCursorPath(r.PathValue("cursor"))
	if !ok {
		writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
		return
	}

	state, err := s.GetSnapshot(documentID, cursor)
	if err != nil {
		if errors.Is(err, events.ErrSnapshotNotFound) {
			writeError(w, http.StatusNotFound, "snapshot not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to load snapshot")
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "state": state})
}

func handleRestore(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern guarantees non-empty

	mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil || mediaType != "application/json" {
		writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
		return
	}

	r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
	var req restoreRequest
	dec := json.NewDecoder(r.Body)
	if err := dec.Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
		return
	}
	if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
		writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
		return
	}

	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}
	if req.ChangeID == "" {
		writeError(w, http.StatusBadRequest, "changeId must be a non-empty string")
		return
	}
	// snapshotCursor must be present and a positive integer (no fractions,
	// strings, booleans, null or zero).
	if len(req.SnapshotCursor) == 0 {
		writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
		return
	}
	snapshotCursor, ok := parsePositiveInt(req.SnapshotCursor)
	if !ok {
		writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
		return
	}

	result, err := s.RestoreSnapshot(documentID, req.DeviceID, req.ChangeID, snapshotCursor)
	if err != nil {
		var conflict *events.ErrRestoreConflict
		switch {
		case errors.Is(err, events.ErrSnapshotNotFound):
			writeError(w, http.StatusNotFound, "snapshot not found")
			return
		case errors.As(err, &conflict):
			writeError(w, http.StatusConflict, "change id already exists with a different deviceId, snapshotCursor or source state: "+req.ChangeID)
			return
		default:
			writeError(w, http.StatusInternalServerError, "failed to restore snapshot")
			return
		}
	}

	writeJSON(w, http.StatusOK, result)
}

// handleSetPermission grants or revokes a registered device's access to one
// document. Devices start authorized, so the first revoke is the first write;
// repeating the current state is idempotent (changed=false). A rejected
// request (bad content type, malformed JSON, trailing content, empty or
// mistyped fields, unknown action) is a 400 JSON error and writes nothing; an
// unregistered device is a 404 JSON error.
func handleSetPermission(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern guarantees non-empty

	var req permissionRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}
	var authorized bool
	switch req.Action {
	case "grant":
		authorized = true
	case "revoke":
		authorized = false
	default:
		writeError(w, http.StatusBadRequest, `action must be "grant" or "revoke"`)
		return
	}

	changed, err := s.SetDocumentPermission(documentID, req.DeviceID, authorized)
	if err != nil {
		if errors.Is(err, store.ErrDeviceNotFound) {
			writeError(w, http.StatusNotFound, "device not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to update permission")
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{
		"deviceId":   req.DeviceID,
		"authorized": authorized,
		"changed":    changed,
	})
}

// parseCursorPath reports whether raw is a decimal non-negative integer and
// returns its value. Signs, fractions and other adornments are rejected.
func parseCursorPath(raw string) (int64, bool) {
	if raw == "" {
		return 0, false
	}
	for _, c := range raw {
		if c < '0' || c > '9' {
			return 0, false
		}
	}
	n, err := strconv.ParseInt(raw, 10, 64)
	if err != nil {
		return 0, false
	}
	return n, true
}

// parseNonNegativeInt reports whether raw is a JSON integer >= 0. Floats,// strings, booleans, null and negative numbers are rejected.
func parseNonNegativeInt(raw json.RawMessage) (int64, bool) {
	var n int64
	if err := json.Unmarshal(raw, &n); err != nil || n < 0 {
		return 0, false
	}
	// Guard against values like 1.0 that Unmarshal into int64 on some inputs;
	// require the literal to contain no fraction or exponent.
	trimmed := strings.TrimSpace(string(raw))
	if trimmed == "" || trimmed[0] == '-' {
		return 0, false
	}
	for _, c := range trimmed {
		if c < '0' || c > '9' {
			return 0, false
		}
	}
	return n, true
}

// parsePositiveInt reports whether raw is a JSON integer >= 1. Zero, floats,
// strings, booleans, null and negative numbers are rejected.
func parsePositiveInt(raw json.RawMessage) (int64, bool) {
	n, ok := parseNonNegativeInt(raw)
	if !ok || n < 1 {
		return 0, false
	}
	return n, true
}

// isJSONObject reports whether raw decodes to a JSON object (not null, an
// array or a scalar).
func isJSONObject(raw json.RawMessage) bool {
	var m map[string]json.RawMessage
	if err := json.Unmarshal(raw, &m); err != nil || m == nil {
		return false
	}
	return true
}

func handleListChanges(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID")

	after, limit, ok := parseChangesQuery(w, r)
	if !ok {
		return
	}

	changes, nextCursor, err := s.ListChanges(documentID, after, limit)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to list changes")
		return
	}

	writeChangesPage(w, changes, nextCursor)
}

// handleSessionChanges is the session-scoped view of the existing change log:
// both path identifiers must be non-empty (the empty-segment guard rejects
// those before routing) and the session must currently exist, after which the
// query behaves exactly like GET /v1/documents/{documentID}/changes — unless
// the session's device has been revoked permission for the document, which is
// a 403 JSON error with no changes or nextCursor. Revocation only gates this
// read; the change log itself is untouched.
func handleSessionChanges(s *app.App, w http.ResponseWriter, r *http.Request) {
	sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
	documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty

	// Malformed query parameters are a request-shape error (400) checked
	// before the resource lookup (404), matching the snapshot GET ordering.
	after, limit, ok := parseChangesQuery(w, r)
	if !ok {
		return
	}

	deviceID, err := s.SessionDevice(sessionID)
	if err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to look up session")
		return
	}

	authorized, err := s.DocumentAuthorized(documentID, deviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to look up permission")
		return
	}
	if !authorized {
		writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		return
	}

	changes, nextCursor, err := s.ListChanges(documentID, after, limit)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to list changes")
		return
	}

	writeChangesPage(w, changes, nextCursor)
}

// parseChangesQuery parses the shared after/limit pagination parameters,
// writing the documented 400 on an illegal value. It is shared by the
// document-scoped and session-scoped change listings so their query semantics
// cannot drift apart.
func parseChangesQuery(w http.ResponseWriter, r *http.Request) (after, limit int64, ok bool) {
	q := r.URL.Query()

	after = 0
	if raw := q.Get("after"); raw != "" {
		v, err := strconv.ParseInt(raw, 10, 64)
		if err != nil || v < 0 {
			writeError(w, http.StatusBadRequest, "after must be a non-negative integer")
			return 0, 0, false
		}
		after = v
	}

	limit = defaultListLimit
	if raw := q.Get("limit"); raw != "" {
		v, err := strconv.ParseInt(raw, 10, 64)
		if err != nil || v < 1 || v > maxListLimit {
			writeError(w, http.StatusBadRequest, "limit must be an integer between 1 and 1000")
			return 0, 0, false
		}
		limit = v
	}

	return after, limit, true
}

// writeChangesPage renders a change listing page in the shared response shape.
func writeChangesPage(w http.ResponseWriter, changes []events.ListedChange, nextCursor int64) {
	writeJSON(w, http.StatusOK, map[string]any{
		"changes":    changes,
		"nextCursor": nextCursor,
	})
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, status int, message string) {
	writeJSON(w, status, map[string]string{"error": message})
}

// handlePollChanges is the long-polling entry over the change log.
//
// Query params share the existing change-read constraints: after is a
// non-negative cursor (default 0) and limit is 1..1000 (default 100); waitMs
// is 0..30000 (default 0). Rows already past after return immediately; a known
// document caught up to after parks until the first new commit or the wait
// deadline; an unknown document returns an empty page with cursor 0 at once.
// The response shape is the ordinary page plus a timedOut flag; a deadline
// expiry echoes the caller's cursor and never advances it. A client
// disconnect simply stops the wait and writes nothing.
func handlePollChanges(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	after, limit, ok := parseChangesQuery(w, r)
	if !ok {
		return
	}
	q := r.URL.Query()
	var waitMs int64
	if raw := q.Get("waitMs"); raw != "" {
		v, err := strconv.ParseInt(raw, 10, 64)
		if err != nil || v < 0 || v > maxPollWaitMillis {
			writeError(w, http.StatusBadRequest, "waitMs must be an integer between 0 and 30000")
			return
		}
		waitMs = v
	}

	changes, nextCursor, timedOut, err := s.WaitForChanges(
		r.Context(), documentID, after, limit, time.Duration(waitMs)*time.Millisecond,
	)
	switch {
	case errors.Is(err, events.ErrStoreClosing):
		writeError(w, http.StatusServiceUnavailable, "service is shutting down")
		return
	case errors.Is(err, context.Canceled), errors.Is(err, context.DeadlineExceeded):
		// The client went away (or, with waitMs bounded, its deadline lapsed
		// at the transport): nothing more to write and nothing was stored.
		return
	case err != nil:
		writeError(w, http.StatusInternalServerError, "failed to poll changes")
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{
		"changes":    changes,
		"nextCursor": nextCursor,
		"timedOut":   timedOut,
	})
}

// handleReplay retries an offline batch against the existing change log. The
// request and per-element semantics mirror POST .../changes — strict
// application/json body, non-empty ids, no in-batch duplicates, idempotent only
// when deviceId and decoded payload match, otherwise 409 reporting the
// conflicting id — with the registration/permission layer enforced first:
// 404 for an unregistered device and 403 for a revoked one, neither exposing
// change content. The whole batch commits in one serialized transaction that
// shares the document's contiguous cursor space with ordinary commits.
func handleReplay(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	var req replayRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}
	if req.Operations == nil {
		writeError(w, http.StatusBadRequest, "operations must be a non-empty array")
		return
	}
	if len(req.Operations) == 0 {
		writeError(w, http.StatusBadRequest, "operations must be a non-empty array")
		return
	}

	changes := make([]events.Change, len(req.Operations))
	seen := make(map[string]struct{}, len(req.Operations))
	for i, op := range req.Operations {
		if op.ID == "" {
			writeError(w, http.StatusBadRequest, "each operation must have a non-empty string id")
			return
		}
		if len(op.Payload) == 0 {
			writeError(w, http.StatusBadRequest, "each operation must carry a JSON payload")
			return
		}
		if _, dup := seen[op.ID]; dup {
			writeError(w, http.StatusBadRequest, "duplicate operation id within batch: "+op.ID)
			return
		}
		seen[op.ID] = struct{}{}
		changes[i] = events.Change{ID: op.ID, DeviceID: req.DeviceID, Payload: op.Payload}
	}

	results, err := s.ReplayChanges(documentID, changes)
	if err != nil {
		var conflict *events.ErrConflict
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			writeError(w, http.StatusNotFound, "device not found")
		case errors.Is(err, store.ErrPermissionDenied):
			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		case errors.As(err, &conflict):
			writeJSON(w, http.StatusConflict, map[string]string{
				"error":      "operation id already exists with different deviceId or payload",
				"conflictId": conflict.ID,
			})
		default:
			writeError(w, http.StatusInternalServerError, "failed to replay operations")
		}
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{"results": results})
}

// Package app is the composition root: it opens the one shared database and
// constructs the three independently reusable internal services — the change
// event service, the permission service and the CRDT state service — wiring
// them together only through their internal interfaces.
//
// The services share one SQLite connection (the kernel opens a single
// pooled connection with immediate transactions), so a change commit, a CRDT
// submission or compaction, and a permission change are serialized on the
// same connection and leave no half-written batch. The change event and CRDT
// services take their registration-and-authorization verdict from the
// permission service inside their own transactions (events.Gate / crdt.Gate),
// and the permission service fans a committed revoke out to their
// subscription registries through authz.RevokeSink. No service reaches into
// another service's tables or fields.
//
// App is the single object the entry and HTTP layers use. It promotes each
// service's input/output boundary as its methods while hiding the wiring; it
// adds no authentication and exposes no endpoint of its own.
package app

import (
	"context"
	"encoding/json"
	"time"

	"github.com/alicegogogogogo/local-first-sync-service/internal/authz"
	"github.com/alicegogogogogo/local-first-sync-service/internal/crdt"
	"github.com/alicegogogogogo/local-first-sync-service/internal/events"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// App composes the durable kernel and the three internal services over one
// shared database connection.
type App struct {
	*store.Store

	events *events.Service
	crdt   *crdt.Service

	// Authz is the permission service. It is exposed so the HTTP layer can
	// grant/revoke and read authorization directly; the other services reach
	// it through their gates rather than this field.
	Authz *authz.Service
}

// Open opens (creating if needed) the SQLite database at path and constructs
// every internal service over it. The empty path opens a private in-memory
// database useful for tests. A construction failure closes the kernel and
// leaves nothing behind.
func Open(path string) (*App, error) {
	kernel, err := store.Open(path)
	if err != nil {
		return nil, err
	}

	// The permission service is built first: its gate is a constructor
	// dependency of the change event and CRDT services.
	permissions, err := authz.New(kernel)
	if err != nil {
		_ = kernel.Close()
		return nil, err
	}
	eventService, err := events.New(kernel, permissions)
	if err != nil {
		_ = kernel.Close()
		return nil, err
	}
	crdtService, err := crdt.New(kernel, permissions)
	if err != nil {
		_ = kernel.Close()
		return nil, err
	}

	// A committed revoke ends the affected live subscriptions in both
	// push channels. The dependency is an interface, registered once here, so
	// the permission service never names either subscriber concretely.
	permissions.AddRevokeSink(eventsRevokeSink{eventService})
	permissions.AddRevokeSink(crdtService)

	return &App{
		Store:  kernel,
		events: eventService,
		crdt:   crdtService,
		Authz:  permissions,
	}, nil
}

// eventsRevokeSink adapts the change event service's revoke hook to the
// permission service's RevokeSink interface.
type eventsRevokeSink struct{ e *events.Service }

func (s eventsRevokeSink) PermissionRevoked(documentID, deviceID string) {
	s.e.SignalRevoked(documentID, deviceID)
}

// Events returns the change event service.
func (a *App) Events() *events.Service { return a.events }

// CRDT returns the CRDT state service.
func (a *App) CRDT() *crdt.Service { return a.crdt }

// ---- Change event service boundary (promoted so the entry layer has one
// object; each method delegates verbatim to the events service). ----

// InterruptWaits wakes every parked long poll and every live change-log and
// CRDT subscription without closing the database, so an orderly shutdown
// drains waiting connections (long polls answer 503; subscriptions finish
// with the going-away close) instead of holding the drain hostage.
func (a *App) InterruptWaits() {
	a.events.InterruptWaits()
	a.crdt.InterruptWaits()
}

// Closing reports whether shutdown has begun, covering both push channels.
func (a *App) Closing() bool {
	return a.events.Closing() || a.crdt.Closing()
}

// Close interrupts the in-memory observers, waits for every subscription
// handler to unregister and then releases the shared database handle.
func (a *App) Close() error {
	a.events.InterruptWaits()
	a.crdt.InterruptWaits()
	a.events.WaitDrained()
	a.crdt.WaitDrained()
	return a.Store.Close()
}

// PostChanges delegates to the change event service.
func (a *App) PostChanges(documentID string, changes []events.Change) ([]events.Result, error) {
	return a.events.PostChanges(documentID, changes)
}

// ReplayChanges delegates to the change event service.
func (a *App) ReplayChanges(documentID string, changes []events.Change) ([]events.Result, error) {
	return a.events.ReplayChanges(documentID, changes)
}

// MergeChange delegates to the change event service.
func (a *App) MergeChange(documentID string, baseCursor int64, c events.Change) (events.MergeResult, error) {
	return a.events.MergeChange(documentID, baseCursor, c)
}

// PutSnapshot delegates to the change event service.
func (a *App) PutSnapshot(documentID string, cursor int64, state json.RawMessage) (bool, error) {
	return a.events.PutSnapshot(documentID, cursor, state)
}

// GetSnapshot delegates to the change event service.
func (a *App) GetSnapshot(documentID string, cursor int64) (json.RawMessage, error) {
	return a.events.GetSnapshot(documentID, cursor)
}

// ExportSnapshots delegates to the change event service. A nil to means the
// interval has no upper bound.
func (a *App) ExportSnapshots(documentID string, from int64, to *int64) ([]events.ExportedSnapshot, error) {
	return a.events.ExportSnapshots(documentID, from, to)
}

// RestoreSnapshot delegates to the change event service.
func (a *App) RestoreSnapshot(documentID, deviceID, changeID string, snapshotCursor int64) (events.RestoreResult, error) {
	return a.events.RestoreSnapshot(documentID, deviceID, changeID, snapshotCursor)
}

// ListChanges delegates to the change event service.
func (a *App) ListChanges(documentID string, after, limit int64) ([]events.ListedChange, int64, error) {
	return a.events.ListChanges(documentID, after, limit)
}

// WaitForChanges delegates to the change event service.
func (a *App) WaitForChanges(ctx context.Context, documentID string, after, limit int64, wait time.Duration) ([]events.ListedChange, int64, bool, error) {
	return a.events.WaitForChanges(ctx, documentID, after, limit, wait)
}

// DocumentExists delegates to the change event service.
func (a *App) DocumentExists(documentID string) (bool, error) {
	return a.events.DocumentExists(documentID)
}

// AddSubscription delegates to the change event service.
func (a *App) AddSubscription(documentID, deviceID string) (<-chan struct{}, <-chan struct{}, func()) {
	return a.events.AddSubscription(documentID, deviceID)
}

// ---- Permission service boundary. ----

// SetDocumentPermission delegates to the permission service.
func (a *App) SetDocumentPermission(documentID, deviceID string, authorized bool) (bool, error) {
	return a.Authz.SetDocumentPermission(documentID, deviceID, authorized)
}

// DocumentAuthorized delegates to the permission service.
func (a *App) DocumentAuthorized(documentID, deviceID string) (bool, error) {
	return a.Authz.DocumentAuthorized(documentID, deviceID)
}

// ---- CRDT state service boundary. ----

// SubmitCRDTOps delegates to the CRDT state service.
func (a *App) SubmitCRDTOps(documentID, declaredType string, ops []crdt.Op) ([]crdt.Result, error) {
	return a.crdt.SubmitOps(documentID, declaredType, ops)
}

// GetCRDTState delegates to the CRDT state service.
func (a *App) GetCRDTState(documentID string) (crdt.State, error) {
	return a.crdt.GetState(documentID)
}

// CompactCRDT delegates to the CRDT state service.
func (a *App) CompactCRDT(documentID, deviceID string) (crdt.Snapshot, error) {
	return a.crdt.Compact(documentID, deviceID)
}

// GetCRDTSnapshot delegates to the CRDT state service.
func (a *App) GetCRDTSnapshot(documentID string) (crdt.Snapshot, error) {
	return a.crdt.GetSnapshot(documentID)
}

// OpenCRDTSubscription delegates to the CRDT state service.
func (a *App) OpenCRDTSubscription(documentID, deviceID string) (*crdt.State, *crdt.Subscription, func(), error) {
	return a.crdt.OpenSubscription(documentID, deviceID)
}

// AddCRDTSubscription delegates to the CRDT state service.
func (a *App) AddCRDTSubscription(documentID, deviceID string) (*crdt.Subscription, func()) {
	return a.crdt.AddSubscription(documentID, deviceID)
}

package store

import (
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"errors"
	"fmt"
)

// ErrAttachmentNotFound reports that no attachment exists with the given id.
// The caller maps it to 404.
var ErrAttachmentNotFound = errors.New("attachment not found")

// ErrAttachmentForbidden reports that the device in the path is not the
// device that created the attachment. The caller maps it to 403.
var ErrAttachmentForbidden = errors.New("attachment belongs to another device")

// ErrAttachmentIncomplete reports that a finish was attempted before every
// chunk arrived, or the received bytes do not add up to the declared total.
// The upload stays resumable; the caller maps it to 409.
var ErrAttachmentIncomplete = errors.New("attachment chunks are missing or shorter than the declared total")

// ErrAttachmentDigestMismatch reports that the assembled content does not
// hash to the declared digest. The attachment stays incomplete; the caller
// maps it to 422.
var ErrAttachmentDigestMismatch = errors.New("assembled content does not match the declared sha256")

// ErrAttachmentDigestConflict reports that a different-size completed content
// already exists under the same digest, so this upload cannot be finished or
// reused. The upload stays resumable; the caller maps it to 409.
var ErrAttachmentDigestConflict = errors.New("a completed content with the same digest but a different size exists")

// ErrAttachmentConflict reports that an attachment id is already taken — by
// another device, or by this device with different metadata. The original
// record is unchanged; the caller maps it to 409.
type ErrAttachmentConflict struct {
	ID string
}

func (e *ErrAttachmentConflict) Error() string {
	return fmt.Sprintf("attachment %q already exists with different owner or metadata", e.ID)
}

// ErrAttachmentSealed reports a chunk write to an upload that was already
// finished. A sealed attachment is immutable: every further chunk write —
// even a byte-identical resubmission — is rejected and the recorded state and
// content are left unchanged. The caller maps it to 409.
var ErrAttachmentSealed = errors.New("attachment is complete and no longer accepts chunks")

// ErrChunkInvalid reports a chunk that violates the upload's declared shape:
// an out-of-range index, a non-final chunk shorter than the declared chunk
// size, or a final chunk beyond the declared total. The caller maps it to
// 400; nothing is written.
type ErrChunkInvalid struct {
	Reason string
}

func (e *ErrChunkInvalid) Error() string { return e.Reason }

// ErrChunkConflict reports that a chunk index already holds different bytes.
// The first content is kept; the caller maps it to 409.
type ErrChunkConflict struct {
	Index int64
}

func (e *ErrChunkConflict) Error() string {
	return fmt.Sprintf("chunk %d already exists with different content", e.Index)
}

// ErrChunkNotFound reports that no chunk exists at the given index. The
// caller maps it to 404.
var ErrChunkNotFound = errors.New("chunk not found")

// Attachment is the stored metadata of one resumable upload.
type Attachment struct {
	ID         string
	DeviceID   string
	TotalBytes int64
	ChunkSize  int64
	SHA256     string
	Complete   bool
	Reused     bool
}

// CompleteResult reports the outcome of a successful (or repeated) finish.
type CompleteResult struct {
	ID       string `json:"attachmentId"`
	Size     int64  `json:"size"`
	SHA256   string `json:"sha256"`
	Complete bool   `json:"complete"`
	Reused   bool   `json:"reused"`
}

// chunkCount returns how many chunks the declared shape implies.
func (a Attachment) chunkCount() int64 {
	return (a.TotalBytes + a.ChunkSize - 1) / a.ChunkSize
}

// checkChunkShape validates index and len(data) against the declared
// totalBytes/chunkSize, returning *ErrChunkInvalid on any violation.
func (a Attachment) checkChunkShape(index int64, length int64) error {
	count := a.chunkCount()
	if index < 0 || index >= count {
		return &ErrChunkInvalid{Reason: fmt.Sprintf("chunk index %d is out of range [0, %d)", index, count)}
	}
	if index < count-1 {
		if length != a.ChunkSize {
			return &ErrChunkInvalid{Reason: fmt.Sprintf("non-final chunk %d must be exactly %d bytes", index, a.ChunkSize)}
		}
		return nil
	}
	remaining := a.TotalBytes - a.ChunkSize*(count-1)
	if length < 1 || length > remaining {
		return &ErrChunkInvalid{Reason: fmt.Sprintf("final chunk must be between 1 and %d bytes", remaining)}
	}
	return nil
}

// loadAttachmentTx loads an attachment row inside tx without any ownership
// judgment; an unknown id yields ErrAttachmentNotFound.
func loadAttachmentTx(tx *sql.Tx, id string) (Attachment, error) {
	var a Attachment
	var complete, reused int
	err := tx.QueryRow(
		`SELECT id, device_id, total_bytes, chunk_size, sha256, complete, reused
		 FROM attachments WHERE id = ?`, id,
	).Scan(&a.ID, &a.DeviceID, &a.TotalBytes, &a.ChunkSize, &a.SHA256, &complete, &reused)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return Attachment{}, ErrAttachmentNotFound
	case err != nil:
		return Attachment{}, err
	}
	a.Complete = complete != 0
	a.Reused = reused != 0
	return a, nil
}

// getAttachmentTx loads an attachment row inside tx and enforces ownership:
// an unknown id yields ErrAttachmentNotFound and a device other than the
// creator yields ErrAttachmentForbidden.
func getAttachmentTx(tx *sql.Tx, id, deviceID string) (Attachment, error) {
	a, err := loadAttachmentTx(tx, id)
	if err != nil {
		return Attachment{}, err
	}
	if a.DeviceID != deviceID {
		return Attachment{}, ErrAttachmentForbidden
	}
	return a, nil
}

// getAttachmentReadTx loads an attachment row inside tx and enforces read
// access: the creator, or a device the creator has granted access through
// SetAttachmentAccess, may read; any other device yields
// ErrAttachmentForbidden. An unknown id yields ErrAttachmentNotFound.
func getAttachmentReadTx(tx *sql.Tx, id, deviceID string) (Attachment, error) {
	a, err := loadAttachmentTx(tx, id)
	if err != nil {
		return Attachment{}, err
	}
	if a.DeviceID == deviceID {
		return a, nil
	}
	granted, err := attachmentAccessGrantedTx(tx, id, deviceID)
	if err != nil {
		return Attachment{}, err
	}
	if !granted {
		return Attachment{}, ErrAttachmentForbidden
	}
	return a, nil
}

// attachmentAccessGrantedTx reports whether deviceID currently holds read
// access to the attachment. Every (attachment, device) pair starts
// unauthorized, so an absent row means not granted.
func attachmentAccessGrantedTx(tx *sql.Tx, attachmentID, deviceID string) (bool, error) {
	var stored int
	err := tx.QueryRow(
		`SELECT authorized FROM attachment_access WHERE attachment_id = ? AND device_id = ?`,
		attachmentID, deviceID,
	).Scan(&stored)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return false, nil
	case err != nil:
		return false, err
	default:
		return stored != 0, nil
	}
}

// CreateAttachment registers a new resumable upload owned by deviceID.
//
//   - An unregistered device yields ErrDeviceNotFound; nothing is written.
//   - Re-posting identical metadata under the same device is idempotent
//     (created=false).
//   - An id already taken — by another device (even with identical metadata)
//     or by this device with different metadata — yields
//     *ErrAttachmentConflict; the original record is unchanged.
//
// The check and the insert run in one serialized transaction and commit
// synchronously, so a retry after a crash reaches the same decision.
func (s *Store) CreateAttachment(deviceID string, a Attachment) (created bool, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	var deviceExists bool
	if err := tx.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM devices WHERE id = ?)`, deviceID,
	).Scan(&deviceExists); err != nil {
		return false, err
	}
	if !deviceExists {
		return false, ErrDeviceNotFound
	}

	var owner string
	var totalBytes, chunkSize int64
	var digest string
	err = tx.QueryRow(
		`SELECT device_id, total_bytes, chunk_size, sha256 FROM attachments WHERE id = ?`, a.ID,
	).Scan(&owner, &totalBytes, &chunkSize, &digest)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		// The creation sequence is one past the current maximum, assigned
		// inside the same serialized transaction as the insert, so values are
		// unique, monotone and never reused — a deleted id that is created
		// again lists as a brand-new record at the end.
		if _, err := tx.Exec(
			`INSERT INTO attachments (id, device_id, total_bytes, chunk_size, sha256, complete, reused, created_seq)
			 VALUES (?, ?, ?, ?, ?, 0, 0, (SELECT COALESCE(MAX(created_seq), 0) + 1 FROM attachments))`,
			a.ID, deviceID, a.TotalBytes, a.ChunkSize, a.SHA256,
		); err != nil {
			return false, err
		}
		if err := tx.Commit(); err != nil {
			return false, err
		}
		return true, nil
	case err != nil:
		return false, err
	}

	if owner != deviceID || totalBytes != a.TotalBytes || chunkSize != a.ChunkSize || digest != a.SHA256 {
		return false, &ErrAttachmentConflict{ID: a.ID}
	}
	return false, tx.Commit()
}

// PutChunk stores one chunk of an upload, durably, inside one transaction.
//
// Ownership and shape are enforced first: an unknown attachment yields
// ErrAttachmentNotFound, a non-creator device ErrAttachmentForbidden, and an
// out-of-range index or wrong length *ErrChunkInvalid — none of these write
// anything. A finished upload is sealed: any further chunk write, even a
// byte-identical resubmission, yields ErrAttachmentSealed and changes
// nothing. On an open upload, re-submitting identical bytes for an existing
// index is idempotent (created=false); different bytes for the same index
// yield *ErrChunkConflict and the first content is kept. Chunks may arrive in
// any order.
func (s *Store) PutChunk(deviceID, attachmentID string, index int64, data []byte) (created bool, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	a, err := getAttachmentTx(tx, attachmentID, deviceID)
	if err != nil {
		return false, err
	}
	// A sealed upload is immutable: reject every further write before any
	// shape check or content comparison, so the recorded state and content
	// cannot change once the finish committed.
	if a.Complete {
		return false, ErrAttachmentSealed
	}
	if err := a.checkChunkShape(index, int64(len(data))); err != nil {
		return false, err
	}

	var existing []byte
	err = tx.QueryRow(
		`SELECT data FROM attachment_chunks WHERE attachment_id = ? AND idx = ?`,
		attachmentID, index,
	).Scan(&existing)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		if _, err := tx.Exec(
			`INSERT INTO attachment_chunks (attachment_id, idx, data) VALUES (?, ?, ?)`,
			attachmentID, index, data,
		); err != nil {
			return false, err
		}
		if err := tx.Commit(); err != nil {
			return false, err
		}
		return true, nil
	case err != nil:
		return false, err
	}

	if !bytesEqual(existing, data) {
		return false, &ErrChunkConflict{Index: index}
	}
	return false, tx.Commit()
}

// reuseContentTx resolves the digest-addressed content reuse decision inside
// tx: it returns reused=true when finished content with the same digest and
// size already exists (the bytes are not copied), reused=false when no such
// content exists yet (the caller inserts it), and ErrAttachmentDigestConflict
// when a finished content carries the same digest but a different size. That
// last state cannot arise from honest chunk assembly without a hash collision,
// but it must never silently reuse mismatched bytes.
func reuseContentTx(tx *sql.Tx, digest string, size int64) (bool, error) {
	var contentSize int64
	err := tx.QueryRow(
		`SELECT size FROM attachment_contents WHERE sha256 = ?`, digest,
	).Scan(&contentSize)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return false, nil
	case err != nil:
		return false, err
	case contentSize != size:
		return false, ErrAttachmentDigestConflict
	default:
		return true, nil
	}
}

// CompleteAttachment seals an upload: every declared chunk must be present
// and their lengths must add up to the declared total, after which the
// concatenated content must hash to the declared digest.
//
//   - Unknown attachment: ErrAttachmentNotFound; non-creator device:
//     ErrAttachmentForbidden.
//   - Missing chunks or a total-length mismatch: ErrAttachmentIncomplete; the
//     upload stays resumable.
//   - Digest mismatch: ErrAttachmentDigestMismatch; the upload stays
//     incomplete.
//   - A completed content with the same digest but a different size:
//     ErrAttachmentDigestConflict; the upload stays resumable.
//   - A completed content with the same digest and size is reused: the bytes
//     are not copied and the result carries Reused=true.
//
// A successful finish is persisted with its result, so repeating the call
// returns the same result without recomputing anything.
func (s *Store) CompleteAttachment(deviceID, attachmentID string) (CompleteResult, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return CompleteResult{}, err
	}
	defer func() { _ = tx.Rollback() }()

	a, err := getAttachmentTx(tx, attachmentID, deviceID)
	if err != nil {
		return CompleteResult{}, err
	}
	if a.Complete {
		// A repeat finish returns the recorded result unchanged.
		return CompleteResult{
			ID:       a.ID,
			Size:     a.TotalBytes,
			SHA256:   a.SHA256,
			Complete: true,
			Reused:   a.Reused,
		}, tx.Commit()
	}

	rows, err := tx.Query(
		`SELECT idx, data FROM attachment_chunks WHERE attachment_id = ? ORDER BY idx ASC`,
		attachmentID,
	)
	if err != nil {
		return CompleteResult{}, err
	}
	var content []byte
	var received int64
	var total int64
	var prevIndex int64 = -1
	complete := true
	for rows.Next() {
		var idx int64
		var data []byte
		if err := rows.Scan(&idx, &data); err != nil {
			_ = rows.Close()
			return CompleteResult{}, err
		}
		if idx != prevIndex+1 {
			complete = false
		}
		prevIndex = idx
		received++
		total += int64(len(data))
		content = append(content, data...)
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return CompleteResult{}, err
	}
	_ = rows.Close()

	if !complete || received != a.chunkCount() || total != a.TotalBytes {
		return CompleteResult{}, ErrAttachmentIncomplete
	}

	sum := sha256.Sum256(content)
	if hex.EncodeToString(sum[:]) != a.SHA256 {
		return CompleteResult{}, ErrAttachmentDigestMismatch
	}

	// Content is addressed by digest: an existing row means another finished
	// attachment already stored these bytes.
	reused, err := reuseContentTx(tx, a.SHA256, a.TotalBytes)
	if err != nil {
		return CompleteResult{}, err
	}
	if !reused {
		if _, err := tx.Exec(
			`INSERT INTO attachment_contents (sha256, size, data) VALUES (?, ?, ?)`,
			a.SHA256, a.TotalBytes, content,
		); err != nil {
			return CompleteResult{}, err
		}
	}

	if _, err := tx.Exec(
		`UPDATE attachments SET complete = 1, reused = ? WHERE id = ?`,
		boolToInt(reused), attachmentID,
	); err != nil {
		return CompleteResult{}, err
	}
	if err := tx.Commit(); err != nil {
		return CompleteResult{}, err
	}
	return CompleteResult{
		ID:       a.ID,
		Size:     a.TotalBytes,
		SHA256:   a.SHA256,
		Complete: true,
		Reused:   reused,
	}, nil
}

// GetAttachment returns the stored metadata of an upload together with the
// sorted indices of the chunks received so far. An unknown id yields
// ErrAttachmentNotFound; a device that is neither the creator nor a granted
// reader yields ErrAttachmentForbidden.
func (s *Store) GetAttachment(deviceID, attachmentID string) (Attachment, []int64, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return Attachment{}, nil, err
	}
	defer func() { _ = tx.Rollback() }()

	a, err := getAttachmentReadTx(tx, attachmentID, deviceID)
	if err != nil {
		return Attachment{}, nil, err
	}

	rows, err := tx.Query(
		`SELECT idx FROM attachment_chunks WHERE attachment_id = ? ORDER BY idx ASC`,
		attachmentID,
	)
	if err != nil {
		return Attachment{}, nil, err
	}
	indices := make([]int64, 0)
	for rows.Next() {
		var idx int64
		if err := rows.Scan(&idx); err != nil {
			_ = rows.Close()
			return Attachment{}, nil, err
		}
		indices = append(indices, idx)
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return Attachment{}, nil, err
	}
	_ = rows.Close()

	return a, indices, tx.Commit()
}

// GetAttachmentChunk returns the bytes stored at index. An unknown attachment
// yields ErrAttachmentNotFound and a device that is neither the creator nor a
// granted reader yields ErrAttachmentForbidden.
// For a known attachment, a negative index or one beyond the declared chunk
// range yields *ErrChunkInvalid (the caller maps it to 400); an in-range index
// with no stored chunk yields ErrChunkNotFound (404).
func (s *Store) GetAttachmentChunk(deviceID, attachmentID string, index int64) ([]byte, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer func() { _ = tx.Rollback() }()

	a, err := getAttachmentReadTx(tx, attachmentID, deviceID)
	if err != nil {
		return nil, err
	}
	// The path index is already a non-negative decimal; reject one outside the
	// shape the creator declared so out-of-range reads fail as a 400 rather than
	// masquerading as a missing chunk (404).
	if index < 0 || index >= a.chunkCount() {
		return nil, &ErrChunkInvalid{Reason: fmt.Sprintf("chunk index %d is out of range [0, %d)", index, a.chunkCount())}
	}

	var data []byte
	err = tx.QueryRow(
		`SELECT data FROM attachment_chunks WHERE attachment_id = ? AND idx = ?`,
		attachmentID, index,
	).Scan(&data)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return nil, ErrChunkNotFound
	case err != nil:
		return nil, err
	}
	return data, tx.Commit()
}

// DeleteAttachment removes the attachment owned by deviceID together with
// every trace it left behind: the received chunks, the completion state and
// every access grant. An unknown id yields ErrAttachmentNotFound and a device
// other than the creator yields ErrAttachmentForbidden — neither writes
// anything, so a repeat delete misses the same way a never-created id does.
//
// Finished content is addressed by digest and shared across attachments, so
// the stored bytes are reclaimed only when the deleted attachment was the
// last completed one referencing them; other finished attachments with the
// same digest keep reading their content unchanged. An incomplete upload
// references no shared content, so deleting it only drops its chunks.
//
// The check, the row removals and the content reclamation run in one
// serialized transaction that commits synchronously, so concurrent deletes of
// the same attachment commit at most once and a restart still finds the
// attachment gone.
func (s *Store) DeleteAttachment(deviceID, attachmentID string) error {
	tx, err := s.db.Begin()
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback() }()

	a, err := getAttachmentTx(tx, attachmentID, deviceID)
	if err != nil {
		return err
	}

	if _, err := tx.Exec(
		`DELETE FROM attachment_access WHERE attachment_id = ?`, attachmentID,
	); err != nil {
		return err
	}
	if _, err := tx.Exec(
		`DELETE FROM attachment_chunks WHERE attachment_id = ?`, attachmentID,
	); err != nil {
		return err
	}
	if _, err := tx.Exec(
		`DELETE FROM attachments WHERE id = ?`, attachmentID,
	); err != nil {
		return err
	}

	// Reclaim the digest-addressed content only when no completed attachment
	// references it any longer.
	if a.Complete {
		var stillReferenced bool
		if err := tx.QueryRow(
			`SELECT EXISTS(SELECT 1 FROM attachments WHERE sha256 = ? AND complete = 1)`,
			a.SHA256,
		).Scan(&stillReferenced); err != nil {
			return err
		}
		if !stillReferenced {
			if _, err := tx.Exec(
				`DELETE FROM attachment_contents WHERE sha256 = ?`, a.SHA256,
			); err != nil {
				return err
			}
		}
	}
	return tx.Commit()
}

// SetAttachmentAccess grants or revokes targetDeviceID's read access to the
// attachment, on behalf of callerDeviceID. Every (attachment, device) pair
// starts unauthorized, so the first grant is the first write for the pair
// (changed=true); repeating the state that already holds writes nothing and
// reports changed=false. An unknown attachment yields ErrAttachmentNotFound,
// a caller other than the creator ErrAttachmentForbidden, and an unregistered
// target device ErrDeviceNotFound — none of these write anything. The lookup
// and the write run in one serialized transaction, so concurrent grant/revoke
// calls each commit completely and the final state matches the last committed
// action. Access only widens the read paths; chunk writes and the finish stay
// creator-only, and a revoke never deletes stored chunks or sealed content.
func (s *Store) SetAttachmentAccess(callerDeviceID, attachmentID, targetDeviceID string, authorized bool) (changed bool, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	a, err := loadAttachmentTx(tx, attachmentID)
	if err != nil {
		return false, err
	}
	if a.DeviceID != callerDeviceID {
		return false, ErrAttachmentForbidden
	}
	exists, err := DeviceExistsTx(tx, targetDeviceID)
	if err != nil {
		return false, err
	}
	if !exists {
		return false, ErrDeviceNotFound
	}

	current, err := attachmentAccessGrantedTx(tx, attachmentID, targetDeviceID)
	if err != nil {
		return false, err
	}
	if current == authorized {
		return false, tx.Commit()
	}

	if authorized {
		// A (re-)grant takes the next position past the attachment's newest
		// grant, assigned inside the same serialized transaction, so the
		// access list orders devices by their latest grant and a position is
		// never reused even after the previous holder was revoked.
		var nextSeq int64
		if err := tx.QueryRow(
			`SELECT COALESCE(MAX(granted_seq), 0) + 1 FROM attachment_access WHERE attachment_id = ?`,
			attachmentID,
		).Scan(&nextSeq); err != nil {
			return false, err
		}
		if _, err := tx.Exec(
			`INSERT INTO attachment_access (attachment_id, device_id, authorized, granted_seq) VALUES (?, ?, 1, ?)
			 ON CONFLICT (attachment_id, device_id) DO UPDATE SET authorized = 1, granted_seq = excluded.granted_seq`,
			attachmentID, targetDeviceID, nextSeq,
		); err != nil {
			return false, err
		}
	} else {
		// A revoke only clears the verdict; the row and its last grant
		// position stay on disk, so an unchanged ledger is byte-for-byte
		// stable and a later re-grant simply takes a new position.
		if _, err := tx.Exec(
			`UPDATE attachment_access SET authorized = 0
			 WHERE attachment_id = ? AND device_id = ?`,
			attachmentID, targetDeviceID,
		); err != nil {
			return false, err
		}
	}
	if err := tx.Commit(); err != nil {
		return false, err
	}
	return true, nil
}

// ListedAttachment is one entry of a device's attachment listing: the stored
// metadata, whether the listing device created the attachment, and the sorted
// indices of the chunks received so far.
type ListedAttachment struct {
	Attachment
	Owned          bool
	ReceivedChunks []int64
}

// ListAttachments returns the page of attachments visible to deviceID: every
// attachment the device created plus every attachment another device created
// and granted it read access to, each appearing at most once. Entries are
// ordered by creation sequence ascending — a stable order that survives
// restarts and never reuses a position, so a deleted id that is created again
// lists as a new record at the end — and paginated by limit/offset. An
// unregistered device yields ErrDeviceNotFound and no listing. The read runs
// in one serialized transaction and writes nothing.
func (s *Store) ListAttachments(deviceID string, limit, offset int64) ([]ListedAttachment, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer func() { _ = tx.Rollback() }()

	exists, err := DeviceExistsTx(tx, deviceID)
	if err != nil {
		return nil, err
	}
	if !exists {
		return nil, ErrDeviceNotFound
	}

	rows, err := tx.Query(
		`SELECT a.id, a.device_id, a.total_bytes, a.chunk_size, a.sha256, a.complete
		 FROM attachments a
		 WHERE a.device_id = ?
			OR EXISTS (SELECT 1 FROM attachment_access ac
				WHERE ac.attachment_id = a.id AND ac.device_id = ? AND ac.authorized <> 0)
		 ORDER BY a.created_seq ASC
		 LIMIT ? OFFSET ?`,
		deviceID, deviceID, limit, offset,
	)
	if err != nil {
		return nil, err
	}
	items := make([]ListedAttachment, 0)
	for rows.Next() {
		var item ListedAttachment
		var complete int
		if err := rows.Scan(
			&item.ID, &item.DeviceID, &item.TotalBytes, &item.ChunkSize, &item.SHA256, &complete,
		); err != nil {
			_ = rows.Close()
			return nil, err
		}
		item.Complete = complete != 0
		item.ReceivedChunks = make([]int64, 0)
		items = append(items, item)
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return nil, err
	}
	_ = rows.Close()

	for i := range items {
		items[i].Owned = items[i].DeviceID == deviceID
		chunkRows, err := tx.Query(
			`SELECT idx FROM attachment_chunks WHERE attachment_id = ? ORDER BY idx ASC`,
			items[i].ID,
		)
		if err != nil {
			return nil, err
		}
		for chunkRows.Next() {
			var idx int64
			if err := chunkRows.Scan(&idx); err != nil {
				_ = chunkRows.Close()
				return nil, err
			}
			items[i].ReceivedChunks = append(items[i].ReceivedChunks, idx)
		}
		if err := chunkRows.Err(); err != nil {
			_ = chunkRows.Close()
			return nil, err
		}
		_ = chunkRows.Close()
	}

	return items, tx.Commit()
}

// ListAttachmentAccess returns the page of device ids that currently hold
// granted read access to the attachment, each at most once, ordered by the
// time their latest grant took effect ascending: the grant sequence is
// assigned one past the attachment's maximum inside the granting
// transaction, so a device revoked and re-granted moves to the position of
// the new grant and never appears twice. The creator itself is never in the
// roster: its reads come from ownership, so a grant or revoke aimed at the
// creator's own id neither adds nor removes an entry. Only the creator may
// read the list: an unknown attachment yields ErrAttachmentNotFound and a
// device other than the creator ErrAttachmentForbidden, judged
// independently, and neither writes anything. Pagination matches
// ListAttachments (limit 1..1000, offset non-negative). The read runs in one
// serialized transaction and writes nothing.
func (s *Store) ListAttachmentAccess(callerDeviceID, attachmentID string, limit, offset int64) ([]string, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer func() { _ = tx.Rollback() }()

	a, err := loadAttachmentTx(tx, attachmentID)
	if err != nil {
		return nil, err
	}
	if a.DeviceID != callerDeviceID {
		return nil, ErrAttachmentForbidden
	}

	rows, err := tx.Query(
		`SELECT ac.device_id FROM attachment_access ac
		 WHERE ac.attachment_id = ? AND ac.authorized <> 0 AND ac.device_id <> ?
		 ORDER BY ac.granted_seq ASC, ac.device_id ASC
		 LIMIT ? OFFSET ?`,
		attachmentID, a.DeviceID, limit, offset,
	)
	if err != nil {
		return nil, err
	}
	devices := make([]string, 0)
	for rows.Next() {
		var deviceID string
		if err := rows.Scan(&deviceID); err != nil {
			_ = rows.Close()
			return nil, err
		}
		devices = append(devices, deviceID)
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return nil, err
	}
	_ = rows.Close()

	return devices, tx.Commit()
}

func bytesEqual(a, b []byte) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func boolToInt(b bool) int {
	if b {
		return 1
	}
	return 0
}

// Package authz is the permission service: the durable, per-document and
// per-device authorization ledger together with the system's single revoke
// verdict.
//
// Every (document, device) pair starts authorized; a grant or revoke is
// recorded per pair. The lookup and the write run in one serialized
// transaction on the shared connection and commit to disk, so concurrent
// grant/revoke calls each land as a complete state and survive a restart.
//
// The other services do not read the permission table. They take their
// registration-and-authorization verdict through AuthorizedTx, evaluated
// inside their own write transaction, so a rejected request is judged before
// any document content is observed and the gate and the gated work commit as
// one judgment. Revoking never deletes changes, snapshots, sessions or CRDT
// state; it only produces the denial and, after the revoke commits, notifies
// the registered revoke sinks (the live subscription registries) so they can
// end the affected connections with the one-time, sticky 4403 close.
package authz

import (
	"database/sql"
	"errors"
	"sync"

	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// schema is created when the service is constructed; its shape is unchanged
// from the pre-refactor layout, so authorization rows already on disk stay
// readable.
const schema = `
CREATE TABLE IF NOT EXISTS document_permissions (
	document_id TEXT NOT NULL,
	device_id   TEXT NOT NULL,
	authorized  INTEGER NOT NULL,
	PRIMARY KEY (document_id, device_id)
);
`

// RevokeSink observes a committed revoke. The change event service and the
// CRDT service register themselves to end the affected live subscriptions; a
// sink must not block and must be safe to call after the revoke transaction
// has committed. The permission service depends on this interface alone, so
// the dependency points from the observers toward the verdict and never back.
type RevokeSink interface {
	PermissionRevoked(documentID, deviceID string)
}

// Service is the permission service.
type Service struct {
	db *sql.DB

	mu    sync.Mutex
	sinks []RevokeSink
}

// New constructs the permission service over the shared kernel handle and
// creates its table.
func New(kernel *store.Store) (*Service, error) {
	db := kernel.DB()
	if _, err := db.Exec(schema); err != nil {
		return nil, err
	}
	return &Service{db: db}, nil
}

// AddRevokeSink registers an observer notified after every committed revoke.
// It is called by the composition root while wiring the services, before the
// surface serves requests.
func (s *Service) AddRevokeSink(sink RevokeSink) {
	s.mu.Lock()
	s.sinks = append(s.sinks, sink)
	s.mu.Unlock()
}

// AuthorizedTx is the shared gate: it returns nil when deviceID is registered
// and currently authorized for documentID, store.ErrDeviceNotFound when the
// device is not registered and store.ErrPermissionDenied when its access has
// been revoked. It runs inside the caller's transaction q, so the verdict is
// taken on the same serialized connection as the work it guards, before any
// document content is read.
func (s *Service) AuthorizedTx(q store.DBTX, documentID, deviceID string) error {
	exists, err := store.DeviceExistsTx(q, deviceID)
	if err != nil {
		return err
	}
	if !exists {
		return store.ErrDeviceNotFound
	}
	var stored int
	err = q.QueryRow(
		`SELECT authorized FROM document_permissions WHERE document_id = ? AND device_id = ?`,
		documentID, deviceID,
	).Scan(&stored)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		// No deviation row: devices start authorized.
		return nil
	case err != nil:
		return err
	default:
		if stored == 0 {
			return store.ErrPermissionDenied
		}
		return nil
	}
}

// DeviceAuthorizedTx adapts the shared gate to the change event and CRDT
// services' Gate interface (which names *sql.Tx). The verdict is identical.
func (s *Service) DeviceAuthorizedTx(tx *sql.Tx, documentID, deviceID string) error {
	return s.AuthorizedTx(tx, documentID, deviceID)
}

// SetDocumentPermission grants or revokes deviceID's access to documentID and
// reports whether the stored permission actually changed.
//
// Every device starts authorized for every document, so the first revoke is
// the first write for the pair (changed=true); repeating a state that already
// holds writes nothing and reports changed=false. An unregistered device
// yields store.ErrDeviceNotFound and nothing is written. The lookup and the
// write run in one serialized transaction, so concurrent grant/revoke calls
// each commit completely and the final state matches the last committed
// action. After a revoke commits, every registered sink is notified; a grant
// notifies nothing (a prior revoke already ended the connection stickily).
func (s *Service) SetDocumentPermission(documentID, deviceID string, authorized bool) (changed bool, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	exists, err := store.DeviceExistsTx(tx, deviceID)
	if err != nil {
		return false, err
	}
	if !exists {
		return false, store.ErrDeviceNotFound
	}

	current := true // devices start authorized; a row only records a deviation
	var stored int
	err = tx.QueryRow(
		`SELECT authorized FROM document_permissions WHERE document_id = ? AND device_id = ?`,
		documentID, deviceID,
	).Scan(&stored)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		// No row: the default (authorized) holds.
	case err != nil:
		return false, err
	default:
		current = stored != 0
	}
	if current == authorized {
		return false, tx.Commit()
	}

	v := 0
	if authorized {
		v = 1
	}
	if _, err := tx.Exec(
		`INSERT INTO document_permissions (document_id, device_id, authorized) VALUES (?, ?, ?)
		 ON CONFLICT (document_id, device_id) DO UPDATE SET authorized = excluded.authorized`,
		documentID, deviceID, v,
	); err != nil {
		return false, err
	}
	if err := tx.Commit(); err != nil {
		return false, err
	}

	// A grant cannot unblock a subscription (the first revoke already ended
	// it, stickily); only a revoke needs to end live subscriptions.
	if !authorized {
		s.mu.Lock()
		sinks := append([]RevokeSink(nil), s.sinks...)
		s.mu.Unlock()
		for _, sink := range sinks {
			sink.PermissionRevoked(documentID, deviceID)
		}
	}
	return true, nil
}

// DocumentAuthorized reports whether deviceID currently holds permission for
// documentID. Devices start authorized, so an absent row means authorized.
func (s *Service) DocumentAuthorized(documentID, deviceID string) (bool, error) {
	var stored int
	err := s.db.QueryRow(
		`SELECT authorized FROM document_permissions WHERE document_id = ? AND device_id = ?`,
		documentID, deviceID,
	).Scan(&stored)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return true, nil
	case err != nil:
		return false, err
	default:
		return stored != 0, nil
	}
}

