1	package crdt
2	
3	import (
4		"errors"
5		"sync"
6	)
7	
8	// subKey identifies the set of CRDT state subscriptions belonging to one
9	// device's view of one document: a state-changing commit fans out to every
10	// device set under the document, a permission revoke closes only the one
11	// (document, device) set.
12	type crdtSubKey struct {
13		document string
14		device   string
15	}
16	
17	// Subscription is one in-memory, push-only subscription to a document's
18	// merged CRDT state. States that actually changed the merge are appended in
19	// transaction-commit order and handed to the connection in that order; the
20	// wake channel is merely a coalescing "drain the queue" signal. A permission
21	// revoke targeting the subscription's (document, device) pair is delivered as
22	// a separate, one-shot closed channel so it can neither be missed nor undone
23	// by a later grant on the same connection.
24	//
25	// A subscription leaves no durable trace: nothing is written, a disconnect
26	// simply unregisters, and stopping wakes every subscription once. Pushing
27	// never writes an operation and never moves the merge.
28	type Subscription struct {
29		// mu guards queue.
30		mu sync.Mutex
31		// queue holds merged states in commit order the connection has not
32		// drained yet. It is unbounded: every committed state change must reach
33		// the subscriber exactly once and in order.
34		queue []State
35		// wakes is a 1-buffered "drain now" signal.
36		wakes chan struct{}
37		// revoked is closed once, the first time permission for the keyed pair is
38		// revoked while this subscription is live. Closing is sticky.
39		revoked       chan struct{}
40		revokedClosed bool
41	}
42	
43	// Wake returns the coalescing drain signal.
44	func (x *Subscription) Wake() <-chan struct{} { return x.wakes }
45	
46	// Revoked returns the one-shot revoke signal.
47	func (x *Subscription) Revoked() <-chan struct{} { return x.revoked }
48	
49	// Drain removes and returns every queued merged state in commit order. It
50	// returns nil when the queue is empty.
51	func (x *Subscription) Drain() []State {
52		x.mu.Lock()
53		defer x.mu.Unlock()
54		if len(x.queue) == 0 {
55			return nil
56		}
57		out := x.queue
58		x.queue = nil
59		return out
60	}
61	
62	// deliver appends a committed merged state and pokes the drain signal. It is
63	// non-blocking: a wake already pending covers this state because the consumer
64	// drains the whole queue each time it runs.
65	func (x *Subscription) deliver(state State) {
66		x.mu.Lock()
67		x.queue = append(x.queue, state)
68		x.mu.Unlock()
69		select {
70		case x.wakes <- struct{}{}:
71		default:
72		}
73	}
74	
75	// AddSubscription registers an in-memory subscription to documentID as seen by
76	// deviceID and returns it together with an idempotent unregister that a
77	// client disconnect, a permission close and a service stop may all race to
78	// call.
79	//
80	// Registration precedes the subscriber's first state read, so a
81	// state-changing commit landing between registration and that read is queued
82	// and cannot be missed. If the service is already stopping the wake is
83	// signaled immediately and unregister is a no-op.
84	func (s *Service) AddSubscription(documentID, deviceID string) (*Subscription, func()) {
85		sub := &Subscription{
86			wakes:   make(chan struct{}, 1),
87			revoked: make(chan struct{}),
88		}
89		key := crdtSubKey{document: documentID, device: deviceID}
90	
91		s.subMu.Lock()
92		defer s.subMu.Unlock()
93		if s.closed {
94			close(sub.wakes)
95			return sub, func() {}
96		}
97		s.subWG.Add(1)
98		s.nextSubID++
99		id := s.nextSubID
100		set := s.subs[key]
101		if set == nil {
102			set = make(map[uint64]*Subscription)
103			s.subs[key] = set
104		}
105		set[id] = sub
106		unregister := func() {
107			s.subMu.Lock()
108			if set, ok := s.subs[key]; ok {
109				if _, ok := set[id]; ok {
110					delete(set, id)
111					if len(set) == 0 {
112						delete(s.subs, key)
113					}
114					s.subMu.Unlock()
115					s.subWG.Done()
116					return
117				}
118			}
119			s.subMu.Unlock()
120		}
121		return sub, unregister
122	}
123	
124	// OpenSubscription atomically registers a state subscription and reads the
125	// document's current merged state. It returns:
126	//
127	//   - state: the current merged state, or nil when no CRDT operation has ever
128	//     been committed (the subscriber then waits silently);
129	//   - sub: the live subscription;
130	//   - unregister: idempotent removal.
131	//
132	// Registration and the read happen as one step relative to a SubmitOps commit
133	// — both hold the serialization mutex — so a state-changing commit lands
134	// either inside the returned initial state or in the subscription's queue,
135	// never both and never neither.
136	func (s *Service) OpenSubscription(documentID, deviceID string) (state *State, sub *Subscription, unregister func(), err error) {
137		s.mu.Lock()
138		defer s.mu.Unlock()
139	
140		sub, unregister = s.AddSubscription(documentID, deviceID)
141		current, getErr := s.GetState(documentID)
142		switch {
143		case errors.Is(getErr, ErrNotFound):
144			return nil, sub, unregister, nil
145		case getErr != nil:
146			unregister()
147			return nil, nil, func() {}, getErr
148		}
149		return &current, sub, unregister, nil
150	}
151	
152	// notifySubscribers publishes a newly merged state to every subscription open
153	// on documentID. It is called only after a state-changing transaction has
154	// committed, so every pushed state is durable and states arrive in
155	// transaction-commit order.
156	func (s *Service) notifySubscribers(documentID string, state State) {
157		s.subMu.Lock()
158		var targets []*Subscription
159		for key, set := range s.subs {
