13	// handleCRDTStateSubscribe is the WebSocket subscription to a document's
14	// merged CRDT state, mounted under the session view:
15	//
16	//	GET /v1/sessions/{sessionId}/documents/{documentId}/crdt/state/subscribe
17	//
18	// The subscription identity is entirely the existing session: the session's
19	// owning device is the only credential and no new auth is introduced. The
20	// validation order is fixed and entirely pre-upgrade, writing nothing:
21	//
22	//  1. the request must be a GET carrying a valid WebSocket upgrade handshake
23	//     (400 JSON otherwise; a malformed path is a 400 JSON too),
24	//  2. the session must currently exist (404 JSON),
25	//  3. its device must currently hold permission for the document (403 JSON).
26	//
27	// After the upgrade the server first pushes the current merged state; a
28	// document without any CRDT operation yet sends nothing and waits silently
29	// until its first state appears. From then on every commit that actually
30	// changes the merge — a counter's per-device maximum advancing, the set union
31	// growing, the register's winning value changing — is pushed as one text
32	// frame in transaction-commit order.
33	// Idempotent repeats, rejected regressions and wholly invalid batches change
34	// no state and produce no frame; re-adding an existing set element pushes
35	// nothing either.
36	//
37	// Each message is one text frame whose payload is byte-for-byte the state
38	// read endpoint's body: compact single-line JSON with the keys in type, value
39	// order, terminated by a newline. The connection is push-only: inbound data
40	// frames are read and discarded, ping is answered with pong. A permission
41	// revoke after the upgrade ends the subscription with close code 4403 —
42	// stickily, a re-grant never revives this connection — and a termination
43	// signal ends every subscription with 1001. Subscriptions are not persisted;
44	// after a restart a fresh subscription immediately receives the consistent
45	// current merged state.
46	func handleCRDTStateSubscribe(s *app.App, w http.ResponseWriter, r *http.Request) {
47		sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
48		documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty
49	
50		if !checkWebSocketUpgrade(r) {
51			writeError(w, http.StatusBadRequest, "a WebSocket upgrade handshake is required")
52			return
53		}
54	
55		deviceID, err := s.SessionDevice(sessionID)
56		if err != nil {
57			if errors.Is(err, store.ErrSessionNotFound) {
58				writeError(w, http.StatusNotFound, "session not found")
59				return
60			}
61			writeError(w, http.StatusInternalServerError, "failed to look up session")
62			return
63		}
64		authorized, err := s.DocumentAuthorized(documentID, deviceID)
65		if err != nil {
66			writeError(w, http.StatusInternalServerError, "failed to look up permission")
67			return
68		}
69		if !authorized {
70			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
71			return
72		}
73	
74		conn, err := upgradeWebSocket(w, r)
75		if err != nil {
76			// The 101 could not be written and the connection has been hijacked
77			// (or is gone); no JSON error can be produced and nothing was
78			// registered.
79			return
80		}
81	
82		serveCRDTStateSubscription(r, s, conn, documentID, deviceID)
83	}
84	
85	// serveCRDTStateSubscription runs one upgraded CRDT-state connection to
86	// completion. Registration and the initial state read are one atomic step in
87	// the store, so a state-changing commit lands either inside that initial
88	// state or in the subscription's queue: the first frame is the current merge
89	// and every later frame is strictly newer, in commit order. The method
90	// returns when the client leaves, permission is revoked or the store starts
91	// closing; the hijacked connection is closed on exit.
92	func serveCRDTStateSubscription(r *http.Request, s *app.App, conn *wsConn, documentID, deviceID string) {
93		initial, sub, unregister, err := s.OpenCRDTSubscription(documentID, deviceID)
94		if err != nil {
95			_ = conn.Close(wsCloseInternalError, "internal error")
96			_ = conn.NetClose()
97			return
98		}
99		defer func() {
100			unregister()
101			_ = conn.NetClose()
102		}()
103	
104		clientGone := make(chan struct{})
105		go func() {
106			defer close(clientGone)
107			for {
108				if _, _, readErr := conn.ReadMessage(); readErr != nil {
109					// A malformed frame ends with the RFC protocol-error code; a
110					// client close is already echoed inside ReadMessage; a network
111					// drop needs no frame.
112					var protoErr *wsProtocolErrorString
113					if errors.As(readErr, &protoErr) {
114						_ = conn.Close(wsCloseProtocolError, "protocol error")
115					}
116					return
117				}
118				// Push-only channel: an inbound data frame is read and discarded;
119				// the client cannot submit or mutate any operation over it.
120			}
121		}()
122	
123		// endNow maps a closing store to 1001 and a sticky revoke to 4403, waiting
124		// briefly for the peer's close echo. Termination takes precedence over a
125		// racing revoke. It returns true when the subscription must end.
126		endNow := func() bool {
127			if s.Closing() {
128				endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
129				return true
130			}
131			select {
132			case <-sub.Revoked():
133				endSubscription(conn, clientGone, wsClosePermissionRevoked, "permission revoked")
134				return true
135			default:
136			}
137			return false
138		}
139	
140		// closingOnly honors a termination signal before the first frame; a revoke
141		// racing the initial push is left for the main loop so the state that was
142		// authorized at handshake still reaches the client ahead of the 4403.
143		closingOnly := func() bool {
144			if s.Closing() {
